import { prisma } from "@/lib/prisma";import { mobileApiError,mobileJson,mobileOptions,requireMobileUser } from "@/lib/mobile-api";import { emitToVideoLive } from "@/lib/realtime";
export function OPTIONS(){return mobileOptions()}
export async function POST(request,{params}){try{const user=await requireMobileUser(request),{liveId}=await params,body=await request.json(),action=String(body?.action??"JOIN").toUpperCase(),row=await prisma.videoLiveSession.findUnique({where:{publicId:decodeURIComponent(liveId)}});if(!row||row.status!=="LIVE")throw Object.assign(new Error("Live video is unavailable."),{code:"LIVE_NOT_FOUND"});const ban=await prisma.videoLiveBan.findFirst({where:{sessionId:row.id,userId:user.id,revokedAt:null,OR:[{expiresAt:null},{expiresAt:{gt:new Date()}}]}});if(ban)throw Object.assign(new Error("You are banned from this live video."),{code:"LIVE_BANNED"});if(action==="LIKE"){const updated=await prisma.videoLiveSession.update({where:{id:row.id},data:{likeCount:{increment:1},revision:{increment:1}},select:{likeCount:true,revision:true}}),data={liveId:row.publicId,likeCount:updated.likeCount,revision:updated.revision};emitToVideoLive(row.publicId,"live-video:likes",{success:true,data});return mobileJson({success:true,data})}if(!["JOIN","LEAVE","HEARTBEAT"].includes(action))throw Object.assign(new Error("Unsupported presence action."),{code:"VALIDATION_ERROR"});const active=action!=="LEAVE";await prisma.videoLiveViewer.upsert({where:{sessionId_userId:{sessionId:row.id,userId:user.id}},create:{sessionId:row.id,userId:user.id,active,socketCount:0},update:{active,...(!active?{socketCount:0}:{})}});const viewerCount=await prisma.videoLiveViewer.count({where:{sessionId:row.id,active:true}});const updated=await prisma.videoLiveSession.update({where:{id:row.id},data:{viewerCount,peakViewers:{set:Math.max(row.peakViewers,viewerCount)},revision:{increment:1}},select:{revision:true}}),data={liveId:row.publicId,viewerCount,revision:updated.revision};emitToVideoLive(row.publicId,active?"live-video:viewer-joined":"live-video:viewer-left",{success:true,data:{...data,user:{publicId:user.publicId,name:user.name,profileImage:user.profileImage}}});return mobileJson({success:true,data})}catch(e){return mobileApiError(e,"LIVE_PRESENCE_FAILED")}}
